        w_mem[14] <= w_mem14_new;
        w_mem[15] <= w_mem15_new;
      end 
    end
  end


  always @(*) begin : select_w
    if(round < 16) w_tmp = w_mem[round[3:0]]; 
    else w_tmp = w_new;
