    w_14 = w_mem[14];
    d0 = { w_1[6:0], w_1[31:7] } ^ { w_1[17:0], w_1[31:18] } ^ { 3'b000, w_1[31:3] };
    d1 = { w_14[16:0], w_14[31:17] } ^ { w_14[18:0], w_14[31:19] } ^ { 10'b0000000000, w_14[31:10] };
    w_new = d1 + w_9 + d0 + w_0;
    if(init) begin
      w_mem00_new = block[511:480];
